  'advertiser_faq1_a': 'मोहिमांवर जा आणि "मोहीम तयार करा" वर टॅप करा. मूलभूत माहिती प्रविष्ट करण्यासाठी, तुमची 16:9 क्रिएटिव्ह सामग्री अपलोड करण्यासाठी, लक्ष्यित फ्लीट निवडण्यासाठी, वेळापत्रक आणि बजेट कॉन्फिगर करण्यासाठी आणि पडताळणीसाठी सबमिट करण्यासाठी चरण-दर-चरण सेटअपचे अनुसरण करा.',
  'advertiser_faq1_q': 'ट्रान्झिट जाहिरात मोहीम कशी तयार करावी आणि सुरू करावी?',
  'advertiser_faq2_a': 'आम्ही MP4 (H.264), JPG, PNG आणि HTML5 झिप पॅकेजेसचे समर्थन करतो. मानक रिझोल्यूशन 1920×1080 (16:9 आस्पेक्ट रेशो) आहे, व्हिडिओ जाहिरातींसाठी कमाल कालावधी 30 सेकंद आहे आणि फाइल आकार 50 MB पेक्षा कमी असणे आवश्यक आहे.',
  'advertiser_faq2_q': 'शिफारस केलेली क्रिएटिव्ह वैशिष्ट्ये कोणती आहेत?',
  'advertiser_faq3_a': 'प्रत्येक मोहीम एक ट्रॅक करण्यायोग्य QR ओळख तयार करते. जेव्हा प्रवासी स्क्रीनवर प्रदर्शित केलेला QR कोड स्कॅन करतात, तेव्हा सिस्टम वेळ, स्थान, वाहन आयडी नोंदवते आणि त्यांना तुमच्या लँडिंग पृष्ठावर पुनर्निर्देशित करते.',
  'advertiser_faq3_q': 'स्मार्ट QR कोड लीड ॲट्रिब्युशन कसे कार्य करते?',
  'advertiser_faq4_a': 'मोहिमांवर दैनिक किंवा एकूण बजेट मॉडेलवर शुल्क आकारले जाते. जाहिरात खर्चावर GST (18%) आकारला जातो. पडताळणी मंजुरीनंतर टॅक्स क्रेडिटसह इनव्हॉइस स्वयंचलितपणे तयार होतात.',
  'advertiser_faq4_q': 'बिलिंग, GST इनव्हॉइस आणि कपाती कशा कार्य करतात?',
